on.Out), { BackgroundColor3 = Color3.fromRGB(22,24,29), BackgroundTransparency = .18 }):Play()\n            TweenService:Create(cardEdge, TweenInfo.new(.14), { Transparency = .05 }):Play()\n        end\n    end)\n    card.MouseLeave:Connect(function()\n        if card.Parent then\n            TweenService:Create(card, TweenInfo.new(.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .24 }):Play()\n            TweenService:Create(cardEdge, TweenInfo.new(.16), { Transparency = item.name == chosen and .06 or .24 }):Play()\n        end\n    end)\n    local lastTap = 0\n    local function fire()\n        local now = os.clock()\n        if now - lastTap < .20 then return end\n        lastTap = now\n        if state.kind == \"Gun\" then state.selectedGun = item.name else state.selectedKnife = item.name end\n        save()\n        if not state.enabled then\n            notify(\"Turn Enable on first\", 2)\n        else\n            task.spawn(function()\n                local ok = applyKind(state.kind, true)\n                if ok then notify(\"Skin: \" .. item.name, 2) else notify(\"No 3D model for \" .. item.name, 2) end\n            end)\n        end\n        rebuildGrid()\n    end\n    card.Activated:Connect(fire)\n    state.cards[#state.cards + 1] = card\nend\n\nlocal function updateCountLabel()\n    countLabel.Text = string.format(\"%02d of %d %s\", renderedCount, #currentItems, state.kind == \"Gun\" and \"guns\" or \"knives\")\nend\n\nlocal function appendSkinBatch(generation)\n    if batchLoading or generation ~= rebuildGeneration then return end\n    local first = renderedCount + 1\n    local last = math.min(first + CARD_BATCH - 1, #currentItems)\n    if first > last then return end\n    batchLoading = true\n    local chosen = selectedName()\n    task.spawn(function()\n        for index = first, last do\n            if generation ~= rebuildGeneration or not gridHost.Parent then return end\n   