 b = New(\"TextButton\", { Parent = rarityBar, Size = UDim2.fromOffset(90, 30), BackgroundColor3 = Color3.fromRGB(7,8,11),\n        BackgroundTransparency = .30, BorderSizePixel = 0, Text = rarity, TextColor3 = RARITY_COLOR[rarity] or C.text,\n        TextSize = 12, Font = Enum.Font.GothamBold, AutoButtonColor = false, LayoutOrder = i })\n    corner(b, 9)\n    local rarityEdge = stroke(b, C.border, .24); rarityEdge.Thickness = 1.2\n    b.AutoButtonColor = false\n    local lastTap = 0\n    local function tap()\n        local now = os.clock()\n        if now - lastTap < .18 then return end\n        lastTap = now\n        state.rarity = state.rarity == rarity and nil or rarity\n        for name, btn in pairs(rarityButtons) do\n            local selected = state.rarity == name\n            TweenService:Create(btn, TweenInfo.new(.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {\n                BackgroundColor3 = selected and Color3.fromRGB(22,24,29) or Color3.fromRGB(7,8,11),\n                BackgroundTransparency = selected and .18 or .30,\n                TextColor3 = selected and C.text or (RARITY_COLOR[name] or C.text),\n            }):Play()\n            local edge = btn:FindFirstChildOfClass(\"UIStroke\")\n            if edge then TweenService:Create(edge, TweenInfo.new(.16), { Color = selected and C.accent2 or C.border, Transparency = selected and .05 or .24 }):Play() end\n        end\n        rebuildGrid()\n    end\n    b.Activated:Connect(tap)\n    rarityButtons[rarity] = b\nend\n\npaintKind()\ntask.defer(function()\n    pcall(function()\n        for k, v in pairs(MESH_DB) do\n            if type(v) == \"table\" then\n                addItem(k, v.kind or \"Knife\", v.rarity or \"Godly\", skinIcon(k))\n            end\n        end\n        rebuildGrid()\n    end)\nend)\n\nlocal function paintShot(inst)\n    if not state.enabled then return end\n    local db = MESH_DB[state.selectedGun]\n    if type(db) ~= \"table\" or type(db.br) ~= \"number\" then return end\n    paintFXInst(inst, db, \"Gun\")\nend\n\nlocal shotConn, shotGen = nil, 0\narmShotListen = function()\n    if type(MESH_DB[state.selectedGun]) ~= \"table\" or type(MESH_DB[state.selectedGun].br) ~= \"number\" then return end\n    shotGen += 1\n    local gen = shotGen\n    if shotConn then\n        shotConn:Disconnect()\n        shotConn = nil\n    end\n    shotConn = workspace.DescendantAdded:Connect(function(inst)\n        local cls = inst.ClassName\n        if cls == \"Beam\" or cls == \"Trail\" then paintShot(inst) end\n    end)\n    task.delay(0.35, function()\n        if gen == shotGen and shotConn then\n            shotConn:Disconnect()\n            shotConn = nil\n        end\n    end)\nend\n\nlocal keepQueued = false\nlocal function queueKeep()\n    if keepQueued or not (state.enabled and state.keep) then return end\n    keepQueued = true\n    task.delay(0.4, function()\n        keepQueued = false\n        if state.enabled and state.keep then applyAll(true) end\n    end)\nend\n\nlocal function hookCharacter(character)\n    if not character then return end\n    for _, inst in ipairs(character:GetDescendants()) do removeLegacyShootClone(inst) end\n    character.ChildAdded:Connect(queueKeep)\n    character.DescendantAdded:Connect(function(inst)\n        if removeLegacyShootClone(inst) then return end\n        local cls = inst.ClassName\n        if cls == \"Beam\" or cls == \"Trail\" then paintShot(inst) end\n    end)\nend\nLocalPlayer.CharacterAdded:Connect(function(character)\n    hookCharacter(character)\n    hudIconCache.Equip, hudIconCache.Throw = nil, nil\n    task.delay(0.4, function()\n        if state.enabled and state.keep then applyAll() end\n    end)\nend)\nhookCharacter(LocalPlayer.Character)\npcall(function()\n    local backpack = LocalPlayer:WaitForChild(\"Backpack\", 5)\n    if backpack then\n        for _, inst in ipairs(backpack:GetDescendants()) do removeLegacyShootClone(inst) end\n        backpack.DescendantAdded:Connect(removeLegacyShootClone)\n        backpack.ChildAdded:Connect(queueKeep)\n    end\nend)\ntask.spawn(function()\n    while CTX.win and CTX.win.Parent do\n        if state.enabled and state.keep then\n            task.wait(8)\n            if state.enabled and state.keep then applyAll(true) end\n        else\n            task.wait(2)\n        end\n    end\nend)\n"
